from pathlib import Path
import html, json, shutil, subprocess, sys
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'build/pages'
OUT.mkdir(parents=True,exist_ok=True)
CSS='body{margin:0;background:#faf8f4;color:#242924;font:17px/1.65 system-ui,sans-serif}*{box-sizing:border-box}main{max-width:960px;margin:auto;padding:42px 24px 70px}h1,h2{font-family:Georgia,serif;line-height:1.15}h1{font-size:clamp(2.3rem,6vw,4rem);margin:20px 0}h2{font-size:1.7rem}a{color:#245b4b;text-underline-offset:4px}a:focus-visible,summary:focus-visible{outline:3px solid #a35b24;outline-offset:5px}.eyebrow{font-size:.78rem;text-transform:uppercase;letter-spacing:.12em}.lead{font-size:1.2rem;max-width:720px}.actions{display:flex;gap:16px;flex-wrap:wrap;margin:26px 0}.button{border:1px solid #245b4b;padding:12px 18px;text-decoration:none;font-weight:600}.primary{background:#245b4b;color:#fff}section{border-top:1px solid #c9cec5;padding-top:22px;margin-top:34px}details{border-top:1px solid #d6d9d1;padding:15px 0}summary{cursor:pointer;font-weight:600}details p{max-width:760px}small{color:#596259}footer{margin-top:40px;font-size:.9rem}code{overflow-wrap:anywhere}ul{padding-left:22px}@media(max-width:550px){main{padding:26px 18px}.actions{gap:10px}.button{width:100%;text-align:center}}'
def page(title,body):
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+CSS+'</style></head><body><main><p class="eyebrow">Tony Wu · Practice tools</p>'+body+'<footer><a href="https://haitaowu12.github.io/tony-wu-home/">About Tony Wu</a> · <a href="deployment.json">Publication record</a></footer></main></body></html>'
subprocess.run([sys.executable,str(ROOT/'scripts/build_release.py')],check=True)
for p in (ROOT/'dist').iterdir():
 if p.is_file():shutil.copy2(p,OUT/p.name)
catalog=json.loads((ROOT/'skills/leadership-toolbox/references/catalog.json').read_text())
entries=[]
for m in catalog['methods']:
 e=html.escape
 entries.append('<details><summary>'+e(m['id']+' · '+m['title'])+'</summary><p>'+e(m['job'])+'</p><p><strong>Before you start:</strong> '+e(' '.join(m['profile']['preconditions']))+'</p><p><strong>Output:</strong> '+e(m['profile']['output'])+'</p><p><strong>Evidence:</strong> '+e(m['evidence'])+'</p><a href="https://github.com/haitaowu12/leadership-toolbox/blob/main/skills/leadership-toolbox/'+e(m['file'])+'">Read the method</a></details>')
body='<h1>Leadership Toolbox</h1><p class="lead">Prepare a conversation, clarify a handoff, or work through a technical leadership decision.</p><p>A portable agent skill and a library of 32 methods. Each method records its purpose, prerequisites, steps, expected output, evidence and limits.</p><div class="actions"><a class="button primary" href="leadership-toolbox-skill-0.2.1.zip" download>Download the agent skill</a><a class="button" href="leadership-toolbox-0.2.1.zip" download>Download the full library</a></div><p><small>Version 0.2.1 · <a href="SHA256SUMS">Archive checksums</a> · <a href="https://github.com/haitaowu12/leadership-toolbox">Source and installation</a></small></p><section><h2>Choose a method</h2><p>Open a method to check its fit before using it. The full guide carries its practical steps, alternatives and guardrails.</p>'+''.join(entries)+'</section><section><h2>Use and limits</h2><p>Install the skill in a compatible host and invoke it explicitly. Work with a concrete situation, the people who hold the relevant decisions, and the evidence available to them. Structural checks and model trials do not establish leadership effectiveness or human outcomes.</p></section>'
(OUT/'index.html').write_text(page('Leadership Toolbox — methods for technical leadership',body))
